CREATE TABLE IF NOT EXISTS github_apps (team_id VARCHAR(36) PRIMARY KEY, app_id BIGINT NOT NULL, client_id VARCHAR(64) NOT NULL, slug VARCHAR(100) NULL, `name` VARCHAR(120) NULL, credential text NOT NULL, version INT NOT NULL, updated_by VARCHAR(36) NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, CONSTRAINT github_apps_team FOREIGN KEY (team_id) REFERENCES teams(id));